# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
W=[
E('suave','/swɑːv/','温文尔雅的；圆熟得体的','说话、微笑、应对场面都很顺，像每个动作都没有毛刺。','来自古法语或拉丁 suavis 甜美的、令人舒服的。早期英语也表示亲切宜人，现代常形容社交时自信、得体而有魅力。',[['拉丁 suavis','甜美的、令人愉快的'],['古法语或拉丁来源 → 英语 suave','亲切宜人；后来常指社交姿态圆熟得体']],'a suave host 会从容接话，让场面不尴尬。这个词可以赞赏魅力，也可能暗示太圆滑、像是表演出来的礼貌，具体要看语境。常用来描写男性，但不是只能用于男性。','a suave manner；a suave host；suave and confident。','polite 只需礼貌；suave 还带有从容、世故和魅力。sincere 是真诚，suave 本身不能保证真诚。',('The host remained suave even when the microphone failed.','即使麦克风出了故障，主持人仍从容得体。'),('His suave manner did not convince her that he was sincere.','他圆熟的举止并没有让她相信他是真诚的。'),sources=['https://www.etymonline.com/word/suave','https://www.oxfordlearnersdictionaries.com/definition/english/suave']),
E('suavely','/ˈswɑːvli/','从容得体地；圆滑地','把话接得平稳、漂亮，表面上看不出慌乱或棱角。','suave + -ly，保留词尾不发音的 e，形成副词。',[['英语 suave','举止圆熟得体的'],['英语 suavely','以圆熟得体的方式说话或行动']],'reply suavely 可以是从容礼貌地回答，也可以是用漂亮话轻巧地绕开问题。它描写的是外在表现，不直接告诉你说话内容是否可信。','reply suavely；smile suavely；speak suavely。','calmly 强调平静；suavely 在平静之外，常带社交技巧与魅力，有时也显得油滑。',('He suavely changed the subject when the question became awkward.','问题变得尴尬时，他圆滑地换了话题。'),('She greeted the guests suavely and led them inside.','她从容得体地迎接客人，把他们领进屋内。'),sources=['https://dictionary.cambridge.org/us/pronunciation/english/suavely','https://en.wiktionary.org/wiki/suavely#English']),
E('suavity','/ˈswɑːvəti/','温文尔雅；圆熟得体的风度','把那种没有毛刺、应对自如的社交风度当作一个整体来谈。','经古法语 suavite 等形式，并从拉丁 suavitas 甜美、宜人借入，来自 suavis。现代可和 suave 配对记，但英语名词有更早的独立借入路线。',[['拉丁 suavis → suavitas','宜人的 → 宜人、柔和的性质'],['古法语 suavite；英语 suavity','宜人、温和；后来常指圆熟的社交风度']],'the suavity of his manner 是他举止中的圆熟与从容。它比 charm 更书面，小说人物描写中较容易遇到；有时赞赏，有时用来暗示外表讨喜、内心未必如此。','effortless suavity；an air of suavity；suavity of manner。','suave 形容一个人或举止；suavity 是那种风度。不要把它理解成 sweet food 的甜味，现代普通用法主要谈人。',('The actor gives the character an air of effortless suavity.','这位演员让角色显得从容圆熟，毫不费力。'),('Beneath his suavity, she sensed impatience.','在他温文尔雅的外表下，她察觉到了不耐烦。'),sources=['https://www.etymonline.com/word/suavity','https://en.wiktionary.org/wiki/suavity#English']),
E('assuage','/əˈsweɪdʒ/','缓解；减轻；安抚','原先又尖又难受的一股感觉，被慢慢磨柔和了。','古法语 assoagier、盎格鲁法语 assuager，通常追溯到重建的通俗拉丁 *adsuaviare，由 ad- 使变为与 suavis 甜美、宜人构成。星号表示这个形式由语言学重建。',[['拉丁 ad- + suavis → 重建形式 *adsuaviare','使变为 + 宜人的 → 使柔和'],['古法语 assoagier；盎格鲁法语 assuager','缓和、安抚'],['中古英语 asswagen → assuage','减轻不愉快的感受或强烈需求']],'assuage fears 是让恐惧减弱，assuage guilt 是让内疚不再那么强烈。这里的甜只是词源里的宜人感，不是拿糖去解决问题。事情本身未必解决了，感受可以先得到缓解。','assuage fears；assuage concerns；assuage guilt；assuage hunger。','reassure 常直接接人，让某人放心；assuage 通常接担忧、恐惧、内疚等感受。say reassure her，也常说 assuage her fears。',('The detailed explanation helped assuage their fears.','详细的解释帮助减轻了他们的恐惧。'),('Buying a gift did little to assuage his guilt.','买一份礼物并没有减轻多少他的内疚。'),sources=['https://www.etymonline.com/word/assuage','https://www.oxfordlearnersdictionaries.com/definition/english/assuage'])]
ROOT=dict(id='C1446',meaning='甜美；宜人；使感受柔和',core='SUAV = SWEET / PLEASANT',image='社交举止没有毛刺，是 suave；把心里难受、尖锐的感觉磨柔和，是 assuage。',intro='拉丁 suavis 表示甜美、令人舒服。从味觉的宜人感，可以理解人的圆熟风度，也可以理解让不愉快的情绪缓和下来。',forms='suavis 通向 suave；suavitas 经法语等途径成为 suavity。assuage 经古法语变化而来，拼写不再完整保留 suav，但来源相关。',branches=[['令人舒服的社交姿态','suave','suavely','suavity'],['让难受的感觉缓和','assuage']],contrasts='suave 说表面举止，不能据此断定真诚；assuage 说缓解感受，不能据此断定根本问题已经解决。',practice='His suave reply did little to assuage her concerns.\n\n他圆熟的回答并没能减轻多少她的担忧。',words=[x['word'] for x in W],exclude={})
ROOT['branches']=[[x[0],'；'.join(x[1:])] for x in ROOT['branches']]
if __name__=='__main__':
 for name,data in [('roots_suav',[ROOT]),('words_suav',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
